import polars as pl

def dataframes_equal(df1: pl.DataFrame, df2: pl.DataFrame) -> bool:
    """Check if two polars DataFrames are exactly equal (same schema and same values)."""
    return df1.equals(df2)


# Example usage
df1 = pl.DataFrame({
    "a": [1, 2, 3],
    "b": ["x", "y", "z"]
})

df2 = pl.DataFrame({
    "a": [1, 2, 3],
    "b": ["x", "y", "z"]
})

df3 = pl.DataFrame({
    "a": [1, 2, 3],
    "b": ["x", "y", "w"]
})

print(dataframes_equal(df1, df2))  # True
print(dataframes_equal(df1, df3))  # False

